		db.Choice("terms", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "He keeps one hand on the folder the whole time, as if the papers might believe him and walk off.");
		db.Choice("ask", "Let me ask you something.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
