		db.Conv("duty.swap.pearls", "duty:swap:pearls", "", "Those are real.", 0, 0, "haven");
		db.Node("start");
		db.Say("", "My mother wore them to her wedding and to his funeral and nowhere in between. Every one is knotted. If the string goes, you only lose one.");
		db.Say("", "I want his name on the truck list. Pavel Roux. Fourteen. He's strong.");
		db.Choice("where", "Are they yours to give?", "more", "", "", "", "", "", "call:slot:1", "", "");
		db.Choice("who", "Is he here?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "Let's talk about the list.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "He doesn't touch the pearls. He looks at the door, where a boy is pretending not to wait.");
		db.Choice("ask", "I need to ask you something.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's talk about the list.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "Will you put him on it?");
