		db.Choice("who", "Is any of it for you?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "Let's see what we've got.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "His eyes go to the jar of boiled sweets at the end of the table, and away, and back.");
		db.Choice("ask", "Wait, I've a question.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's see what we've got.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "Can I have them? The things on the list?");
		db.Choice("take", "The list, for the eggs.", "end", "", "", "", "", "", "call:slot:3", "", "");
		db.Choice("no", "Your grandad has to come himself.", "end", "", "", "", "", "", "call:slot:4", "", "");
		db.Choice("third", "The list for four eggs. Keep two.", "end", "", "", "", "", "", "call:slot:5", "", "");
		db.Conv("duty.swap.ring", "duty:swap:ring", "", "About the ring.", 0, 0, "haven");
		db.Node("start");
		db.Say("", "It's a good ring. Gold, not plated. He bought it in the year we had the flood, when there was nothing, so you know he meant it.");
		db.Say("", "Two tins. That's all. It's not for me, before you think it.");
		db.Choice("where", "Is it yours to sell?", "more", "", "", "", "", "", "call:slot:1", "", "");
		db.Choice("who", "Who are the tins for?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "He turns the empty finger with his thumb, round and round, where the ring used to sit.");
		db.Choice("ask", "I've another question.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "So. Two tins, or not.");
		db.Choice("take", "Two tins for the ring.", "end", "", "", "", "", "", "call:slot:3", "", "");
		db.Choice("no", "Keep your ring. I can't take it.", "end", "", "", "", "", "", "call:slot:4", "", "");
		db.Choice("third", "Tins now. The ring, when you can.", "end", "", "", "", "", "", "call:slot:5", "", "");
		db.Conv("duty.swap.salt", "duty:swap:salt", "", "Salt, is it?", 0, 0, "plain");
		db.Node("start");
		db.Say("", "From the pans on the coast. A third of the sack for flour, weight for weight. You know what salt's worth with winter coming.");
		db.Choice("where", "Which pans? Which coast?", "more", "", "", "", "", "", "call:slot:1", "", "");
		db.Choice("who", "Who's the flour for?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "He keeps the sack tied at the bottom with his hand on the knot.");
		db.Choice("ask", "Hold on.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "Weight for weight?");
		db.Choice("take", "Flour for the sack, weight for weight.", "end", "", "", "", "", "", "call:slot:3", "", "");
		db.Choice("no", "No trade.", "end", "", "", "", "", "", "call:slot:4", "", "");
		db.Choice("third", "Flour for the top half, weighed dry.", "end", "", "", "", "", "", "call:slot:5", "", "");
		db.Conv("duty.swap.stolen", "duty:swap:stolen", "", "Where's the spoon from?", 0, 0, "plain");
		db.Node("start");
		db.Say("", "Solid silver, that. Look at the weight. One tin and it's yours, I'm not greedy.");
		db.Say("", "Don't look over there. Look at the spoon.");
		db.Choice("where", "Where did you find it?", "more", "", "", "", "", "", "call:slot:1", "", "");
		db.Choice("who", "Who's the tin for?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "Across the room the old man has his hand over his signet ring, as if it might go next.");
		db.Choice("ask", "Hang on.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "One tin. Quick, before I change my mind.");
		db.Choice("take", "A tin for the spoon.", "end", "", "", "", "", "", "call:slot:3", "", "");
		db.Choice("no", "Put it away.", "end", "", "", "", "", "", "call:slot:4", "", "");
		db.Choice("third", "Let's ask the man whose spoon it is.", "end", "", "", "", "", "", "call:slot:5", "", "");
		db.Conv("duty.swap.tools", "duty:swap:tools", "", "Those are good chisels.", 0, 0, "haven");
		db.Node("start");
		db.Say("", "The best in the valley. My father's, then mine. I'm not selling them. I'm leaving them with you while my hands mend.");
		db.Say("", "Two tins a week while they're on your shelf. I'll want every one back. I'll know if one's missing.");
		db.Choice("where", "What happened to your hands?", "more", "", "", "", "", "", "call:slot:1", "", "");
		db.Choice("who", "Who'll use them meanwhile?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "He unrolls the cloth a little, touches each handle in turn, and rolls it up again.");
		db.Choice("ask", "One thing before we settle.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "Let's settle it.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "Will you keep them?");
		db.Choice("take", "Two tins, and the tools are ours.", "end", "", "", "", "", "", "call:slot:3", "", "");
		db.Choice("no", "We're not a pawnshop.", "end", "", "", "", "", "", "call:slot:4", "", "");
		db.Choice("third", "On the shelf, for a week's work.", "end", "", "", "", "", "", "call:slot:5", "", "");
		db.Conv("duty.swap.watch", "duty:swap:watch", "", "That's a man's watch.", 0, 0, "plain");
		db.Node("start");
		db.Say("", "It goes. Listen. It ticks. You have to wind it in the morning or it stops, I know how, I do it every day.");
		db.Say("", "Bread. A whole one, if you've got a whole one.");
		db.Choice("where", "Where did you get it?", "more", "", "", "", "", "", "call:slot:1", "", "");
		db.Choice("who", "Who's the bread for?", "more", "", "", "", "", "", "call:slot:2", "", "");
		db.Choice("terms", "All right. Let's see.", "terms", "", "", "", "", "", "", "", "");
		db.Node("more");
		db.Say("", "He holds the watch to his ear again while you think, as if it might have stopped since.");
		db.Choice("ask", "Tell me something else.", "start", "", "", "", "", "", "", "", "");
		db.Choice("settle", "All right. Let's see.", "terms", "", "", "", "", "", "", "", "");
		db.Node("terms");
		db.Say("", "Is it a yes?");
		db.Choice("take", "Bread for the watch.", "end", "", "", "", "", "", "call:slot:3", "", "");
		db.Choice("no", "I can't take that watch.", "end", "", "", "", "", "", "call:slot:4", "", "");
		db.Choice("third", "Bread. The watch goes in the book.", "end", "", "", "", "", "", "call:slot:5", "", "");
		db.Conv("duty.toll.bitten", "duty:toll:bitten", "", "Why the long sleeves?", 4, 1, "plain");
		db.Node("start");
		db.Say("", "Cold. It's cold. Everybody's cold. I just want to get to my sister's, that's all, she has a stove.");
		db.Choice("back6", "Right.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("duty.toll.child", "duty:toll:child", "", "Where are your people?", 4, 1, "plain");
		db.Node("start");
		db.Say("", "My aunt's in the next town. She has a blue door. I know the way. I've been once, before, in a car. It was quicker in a car.");
		db.Choice("back4", "Right.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("duty.toll.courier", "duty:toll:courier", "", "What's in the satchel?", 4, 1, "haven");
		db.Node("start");
		db.Say("", "Letters, mostly. A dressing or two. The Haven sends a runner to the farms on this road every third day, and the farms send eggs back. Ask anyone. It's not a secret.");
		db.Choice("back1", "Right.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("duty.toll.deserter", "duty:toll:deserter", "", "That's Bastion kit.", 4, 1, "plain");
		db.Node("start");
		db.Say("", "It was. I've taken the patches off. They sent us to hold a bridge with nine rounds each, and I counted the rounds and counted the dead, and I walked.");
		db.Choice("back2", "Right.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("duty.toll.handcart", "duty:toll:handcart", "", "How old are the little ones?", 4, 1, "plain");
		db.Node("start");
		db.Say("", "Four and six. They walked the first day and then they stopped walking, and now they sleep. I envy them. I've not slept since the roads shut.");
		db.Choice("back0", "Right.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("duty.toll.hunter", "duty:toll:hunter", "", "Good hunting up there?", 4, 1, "plain");
		db.Node("start");
		db.Say("", "Deer's come down out of the high woods. Nobody's shooting them now, so they've stopped being afraid of a man walking. They're still afraid of the other things.");
		db.Choice("back11", "Right.", "hub", "", "", "", "", "", "", "", "");
		db.Conv("duty.toll.oldman", "duty:toll:oldman", "", "What have you got for me?", 4, 1, "plain");
		db.Node("start");
		db.Say("", "Nothing but news, son. And the news is this: the ferry man at the river has stopped taking bread. He takes boots now. Remember that one. It's worth a toll.");
